param([Parameter(Mandatory=$true)][string]$GameRoot,[string]$Output=(Join-Path $PSScriptRoot '../../docs/research/rimworld/evidence/apparel-xml.json'))
$ErrorActionPreference='Stop'
$assembly=(Get-FileHash -LiteralPath (Join-Path $GameRoot 'Assembly-CSharp.dll') -Algorithm SHA256).Hash.ToLowerInvariant()
if($assembly -ne 'eff7d97949f919fb2b151ebfb906e9be749b63410b7dbda78eeebb7972b245c3'){throw 'Review changed source before updating apparel evidence.'}
$garment=@('costStuffCount','costList','stuffCategories','statBases','recipeMaker/workSpeedStat','recipeMaker/workSkill','recipeMaker/workAmount','recipeMaker/productCount','recipeMaker/recipeUsers','recipeMaker/unfinishedThingDef','recipeMaker/skillRequirements','recipeMaker/researchPrerequisite','recipeMaker/researchPrerequisites','apparel/bodyPartGroups','apparel/layers','apparel/wearPerDay','apparel/developmentalStageFilter','comps','equippedStatOffsets')
$stat=@('defaultBaseValue','minValue','maxValue','workerClass','parts','statFactors','skillNeedFactors','capacityFactors','roundValue','roundToFiveOver')
$plant=@('statBases/MaxHitPoints','plant/growDays','plant/harvestedThingDef','plant/harvestYield','plant/harvestTag','plant/fertilityMin','plant/fertilitySensitivity','plant/sowWork','plant/harvestWork','plant/sowMinSkill','plant/sowResearchPrerequisites','plant/harvestMinGrowth','plant/harvestAfterGrowth','plant/harvestFailable','plant/harvestYieldAffectedByDifficulty','plant/sowTags','plant/dieIfLeafless')
$selections=@(
 @('garment','Data/Core/Defs/ThingDefs_Misc/Apparel_Various.xml',"/Defs/ThingDef[@Name='ApparelNoQualityBase' or @Name='ApparelBase' or @Name='ApparelMakeableBase' or defName='Apparel_Parka' or defName='Apparel_Duster' or defName='Apparel_BasicShirt' or defName='Apparel_CollarShirt' or defName='Apparel_Pants']",$garment),
 @('garment','Data/Core/Defs/ThingDefs_Misc/Apparel_Headgear.xml',"/Defs/ThingDef[@Name='HatMakeableBase' or defName='Apparel_Tuque']",$garment),
 @('stat','Data/Core/Defs/Stats/Stats_Apparel.xml',"/Defs/StatDef[@Name='InsulationBase' or defName='Insulation_Cold' or defName='Insulation_Heat' or defName='EquipDelay' or defName='StuffEffectMultiplierInsulation_Cold' or defName='StuffEffectMultiplierInsulation_Heat']",$stat),
 @('stuff','Data/Core/Defs/ThingDefs_Items/Items_Resource_Stuff.xml',"/Defs/ThingDef[defName='Cloth' or defName='WoodLog']",@('statBases','stuffProps/statFactors','stuffProps/statOffsets','stuffProps/statFactorsQuality','stuffProps/statOffsetsQuality','stuffProps/categories','stackLimit')),
 @('resource','Data/Core/Defs/ThingDefs_Items/Items_Resource_Base.xml',"/Defs/ThingDef[@Name='ResourceBase']",@('stackLimit','statBases','stuffProps')),
 @('plant','Data/Core/Defs/ThingDefs_Plants/Plants_Cultivated_Farm.xml',"/Defs/ThingDef[defName='Plant_Cotton']",$plant),
 @('plant','Data/Core/Defs/ThingDefs_Plants/Plants_Bases.xml',"/Defs/ThingDef[@Name='PlantBaseNonEdible' or @Name='PlantBase']",$plant),
 @('bench','Data/Core/Defs/ThingDefs_Buildings/Buildings_Production.xml',"/Defs/ThingDef[@Name='BenchBase' or defName='HandTailoringBench']",@('costStuffCount','costList','stuffCategories','statBases','size','interactionCellOffset','researchPrerequisites','building/workTableRoomRole','building/workTableNotInRoomRoleFactor','comps')),
 @('research','Data/Core/Defs/ResearchProjectDefs/ResearchProjects_1.xml',"/Defs/ResearchProjectDef[defName='ComplexClothing']",@('baseCost','techLevel','prerequisites','tags')),
 @('stat','Data/Core/Defs/Stats/Stats_Building_Special.xml',"/Defs/StatDef[defName='WorkTableWorkSpeedFactor' or defName='WorkToBuild']",$stat),
 @('stat','Data/Core/Defs/Stats/Stats_Pawns_WorkRecipes.xml',"/Defs/StatDef[defName='GeneralLaborSpeed']",$stat),
 @('stat','Data/Core/Defs/Stats/Stats_Basics_General.xml',"/Defs/StatDef[defName='MaxHitPoints' or defName='WorkToMake']",$stat),
 @('body','Data/Core/Defs/Bodies/Bodies_Humanlike.xml',"/Defs/BodyDef[defName='Human']",@('corePart//groups'))
)
function Relative-XPath($leaf,$root){$parts=[Collections.Generic.List[string]]::new();$cursor=$leaf;while($cursor -ne $root){$tag=$cursor.LocalName;$siblings=@($cursor.ParentNode.ChildNodes|Where-Object{$_.NodeType -eq 'Element' -and $_.LocalName -eq $tag});$segment=$tag;if($siblings.Count -gt 1){$segment+='['+([Array]::IndexOf($siblings,$cursor)+1)+']'};$parts.Insert(0,$segment);$cursor=$cursor.ParentNode};return ($parts -join '/')}
$records=[Collections.Generic.List[object]]::new()
foreach($s in $selections){$file=Join-Path $GameRoot $s[1];[xml]$doc=Get-Content -Raw -LiteralPath $file;$sha=(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant();$nodes=$doc.SelectNodes($s[2]);if(!$nodes.Count){throw "No nodes: $($s[2])"}
 foreach($node in $nodes){$def=$node.SelectSingleNode('defName');$name=if($def){$def.InnerText}else{$node.GetAttribute('Name')};$xp='/Defs/'+$node.LocalName+$(if($def){"[defName='$name']"}else{"[@Name='$name']"});$leaves=[Collections.Generic.List[object]]::new();$attrs=[Collections.Generic.List[object]]::new();$absent=[Collections.Generic.List[string]]::new()
  foreach($selector in $s[3]){$chosen=$node.SelectNodes($selector);if(!$chosen.Count){$absent.Add($selector);continue};foreach($top in $chosen){$scan=@($top)+@($top.SelectNodes('.//*'));foreach($child in $scan){$rel=Relative-XPath $child $node;if($rel -match '/(label|description)$'){continue};if($child.Attributes.Count){$a=[ordered]@{};foreach($item in $child.Attributes){$a[$item.Name]=$item.Value};$attrs.Add([ordered]@{xpath=$xp+'/'+$rel;attributes=$a})};if(!$child.SelectNodes('*').Count){$leaves.Add([ordered]@{xpath=$xp+'/'+$rel;value=$child.InnerText})}}}}
  $records.Add([ordered]@{group=$s[0];id=$node.LocalName+'_'+$name;def_name=$name;parent_name=$node.GetAttribute('ParentName');source=[ordered]@{path=$s[1];xpath=$xp;sha256=$sha};selected_paths=$s[3];absent_paths=@($absent.ToArray());fields=@($leaves.ToArray());node_attributes=@($attrs.ToArray())})
 }
}
$result=[ordered]@{evidence_id='RW17-APPAREL-XML';version_text=(Get-Content -Raw -LiteralPath (Join-Path $GameRoot 'Version.txt')).Trim();assembly_sha256=$assembly;kind='Selected direct apparel, textile, crop, workshop and human body-group declarations';limitations=@('Selected apparel and cotton chains are resolved only for reviewed paths; this is not the enabled-mod effective database.','Body snapshot contains group membership only, not complete organs or runtime missing parts.','Static extraction does not execute original gameplay or project implementation.');records=@($records.ToArray())}
[IO.File]::WriteAllText([IO.Path]::GetFullPath($Output),(($result|ConvertTo-Json -Depth 24) -replace "`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false));Write-Output "Recorded $($records.Count) selected apparel XML records."
